        if (jobEvents == null) {
            return source;
        }
        return jobEvents;
    }

    public static SourceFunction<TaskEvent> taskSourceOrTest(SourceFunction<TaskEvent> source) {
        if (taskEvents == null) {
            return source;
        }
        return taskEvents;
    }

