package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.functions.windowing.WindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;
import org.apache.flink.core.fs.FileSystem;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Task events stream
        DataStream<TaskEvent> tasks = env.addSource(AppBase.taskSourceOrTest(new FileSourceTaskEvent(taskInput)))
                .filter(e -> e != null && e.eventType == 0) // SUBMIT
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        // Job events stream
        DataStream<JobEvent> jobs = env.addSource(AppBase.jobSourceOrTest(new FileSourceJobEvent(jobInput)))
                .filter(e -> e != null && e.eventType == 4) // FINISH
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp / 1000)
                );

        // Identify stages and count tasks
        DataStream<Tuple2<Long, Integer>> stageCounts = tasks
                .keyBy(e -> e.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .apply(new WindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow>() {
                    @Override
                    public void apply(Long jobId, TimeWindow window, Iterable<TaskEvent> input, Collector<Tuple2<Long, Integer>> out) {
                        int count = 0;
                        for (TaskEvent e : input) {
                            count++;
                        }
                        out.collect(Tuple2.of(jobId, count));
                    }
                });

        // Find max stage count and emit when job finishes
        DataStream<Tuple2<Long, Integer>> results = stageCounts
                .keyBy(t -> t.f0)
                .connect(jobs.keyBy(e -> e.jobId))
                .process(new LongestStageProcessFunction(sesssize));

        if (AppBase.out != null) {
            results.addSink(AppBase.out);
        } else if (outputPath != null) {
            results.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
        }

        env.execute("LongestSessionPerJob");
    }

    public static class FileSourceTaskEvent implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        public FileSourceTaskEvent(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            if (path == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(path));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    TaskEvent event = TaskEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class FileSourceJobEvent implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        public FileSourceJobEvent(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            if (path == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(path));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    JobEvent event = JobEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class LongestStageProcessFunction extends KeyedCoProcessFunction<Long, Tuple2<Long, Integer>, JobEvent, Tuple2<Long, Integer>> {
        private final int gapSeconds;
        private ValueState<Integer> maxTasksState;

        public LongestStageProcessFunction(int gapSeconds) {
            this.gapSeconds = gapSeconds;
        }

        @Override
        public void open(Configuration parameters) {
            maxTasksState = getRuntimeContext().getState(new ValueStateDescriptor<>("maxTasks", Integer.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer currentMax = maxTasksState.value();
            if (currentMax == null || value.f1 > currentMax) {
                maxTasksState.update(value.f1);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            // Register a timer to emit the result after all possible stages have fired.
            // A stage ends after gapSeconds of inactivity. All SUBMITs for this job 
            // must have happened before or at the time of the Job FINISH event.
            // So by timestamp + gap, all session windows for this job will have fired.
            long timerTime = ctx.timestamp() + (gapSeconds * 1000L) + 1000L;
            ctx.timerService().registerEventTimeTimer(timerTime);
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Integer maxTasks = maxTasksState.value();
            if (maxTasks != null) {
                out.collect(Tuple2.of(ctx.getCurrentKey(), maxTasks));
            }
            maxTasksState.clear();
        }
    }
}

